PREFIX in: <http://data.world/schema/insurance/>

SELECT ?policyNumber (AVG(?claimLoss) AS ?averageLoss)
WHERE {
  SERVICE <mapped> {
    ?claim a in:Claim ;
           in:against ?pcd .

    ?pcd in:hasPolicy ?policy .
    ?policy in:policyNumber ?policyNumber .

    OPTIONAL {
      ?claim in:hasLossPayment ?lp .
      ?lp in:lossPaymentAmount ?lossPaymentAmountRaw .
    }
    OPTIONAL {
      ?claim in:hasLossReserve ?lr .
      ?lr in:lossReserveAmount ?lossReserveAmountRaw .
    }
    OPTIONAL {
      ?claim in:hasExpensePayment ?ep .
      ?ep in:expensePaymentAmount ?expensePaymentAmountRaw .
    }
    OPTIONAL {
      ?claim in:hasExpenseReserve ?er .
      ?er in:expenseReserveAmount ?expenseReserveAmountRaw .
    }

    BIND(COALESCE(xsd:decimal(?lossPaymentAmountRaw), 0) AS ?lossPaymentAmount)
    BIND(COALESCE(xsd:decimal(?lossReserveAmountRaw), 0) AS ?lossReserveAmount)
    BIND(COALESCE(xsd:decimal(?expensePaymentAmountRaw), 0) AS ?expensePaymentAmount)
    BIND(COALESCE(xsd:decimal(?expenseReserveAmountRaw), 0) AS ?expenseReserveAmount)

    BIND((?lossPaymentAmount + ?lossReserveAmount + ?expensePaymentAmount + ?expenseReserveAmount) AS ?claimLoss)
  }
}
GROUP BY ?policyNumber
ORDER BY ?policyNumber

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?policyNumber ?premiumAmount
WHERE {
  SERVICE <mapped> {
    ?coverage a in:PolicyCoverageDetail ;
              in:hasPolicy ?policy ;
              in:hasPremiumAmount ?premium .
    ?policy in:policyNumber ?policyNumber .
    ?premium in:premiumAmount ?premiumAmount .
  }
}
ORDER BY ?policyNumber

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?policyNumber ?coverageEffectiveDate ?coverageExpirationDate ?premiumAmount
WHERE {
  SERVICE <mapped> {
    ?coverage a in:PolicyCoverageDetail ;
              in:hasPolicy ?policy ;
              in:hasPremiumAmount ?premium ;
              in:policyCoverageEffectiveDate ?coverageEffectiveDate ;
              in:policyCoverageExpirationDate ?coverageExpirationDate .

    ?policy in:policyNumber ?policyNumber .

    ?premium in:premiumAmount ?premiumAmount .
  }
}
ORDER BY ?policyNumber ?coverageEffectiveDate ?coverageExpirationDate

PREFIX in: <http://data.world/schema/insurance/>

SELECT DISTINCT ?policyHolder ?claim ?catastrophe
WHERE {
  SERVICE <mapped> {
    ?policy a in:Policy ;
            in:hasPolicyHolder ?policyHolder .

    ?pcd a in:PolicyCoverageDetail ;
         in:hasPolicy ?policy .

    ?claim a in:Claim ;
           in:against ?pcd ;
           in:hasCatastrophe ?catastrophe .
  }
}

PREFIX in: <http://data.world/schema/insurance/>

SELECT (COUNT(DISTINCT ?policy) AS ?policyCount)
WHERE {
  SERVICE <mapped> {
    ?policy a in:Policy .
  }
}
